/* One reusable on-device OCR worker; only public model bytes enter the cache. */
const OCRRuntime=(()=>{
 let worker=null,starting=null,idle=null,generation=0,progress=()=>{};const cancellations=new Set();
 async function stop(){generation++;clearTimeout(idle);for(const cancel of cancellations)cancel(Error('Recognition canceled'));cancellations.clear();const old=worker;worker=null;starting=null;if(old)await old.terminate();}
 async function get(onProgress){clearTimeout(idle);progress=onProgress||(()=>{});if(worker)return worker;if(starting)return starting;const epoch=generation;starting=(async()=>{await loadScript('vendor/tesseract.min.js');const ready=await Tesseract.createWorker('eng',1,{workerPath:new URL('vendor/worker.min.js',document.baseURI).href,corePath:new URL('vendor/',document.baseURI).href,langPath:new URL('vendor/fast/',document.baseURI).href,workerBlobURL:false,cacheMethod:'write',cachePath:'camino-fast-english-v1',logger:m=>{if(epoch===generation)progress(m)}});if(epoch!==generation){await ready.terminate();throw Error('Recognition canceled');}worker=ready;return ready;})();const pending=starting;try{return await pending}catch(e){if(starting===pending)starting=null;throw e;}}
 async function recognize(source,{timeout=45000,onProgress,mode='page'}={}){let timer,rejectCanceled;const epoch=generation;const canceled=new Promise((_,reject)=>{rejectCanceled=reject;cancellations.add(reject)});try{return await Promise.race([(async()=>{const current=await get(onProgress);if(epoch!==generation)throw Error('Recognition canceled');if(current.setParameters)await current.setParameters({tessedit_pageseg_mode:mode==='header'?'11':'3'});return(await current.recognize(source)).data.text})(),canceled,new Promise((_,reject)=>{timer=setTimeout(()=>{reject(Error('Recognition time limit reached. Use a text-based PDF for a faster import.'));stop();},timeout)})]);}finally{cancellations.delete(rejectCanceled);clearTimeout(timer);if(epoch===generation){clearTimeout(idle);idle=setTimeout(()=>stop(),90000);}}}

 return{recognize,stop};
})();
